    const updateClasses = () => {
      elements.circle.classList.remove('active', ...COLOR_MODES);
      if (state.active) elements.circle.classList.add('active');
      if (state.colorMode > 0) elements.circle.classList.add(COLOR_MODES[state.colorMode]);
    };

    const updateUI = () => {
      const hints = state.active
        ? ['Active!', IS_TOUCH ? 'Tap again to change color' : 'Double-click or C to change color', IS_TOUCH ? 'Use Reset' : 'Press R to reset']
        : ['Click to activate', IS_TOUCH ? 'Tap twice for color' : 'Double-click or C to cycle', 'Use Reset'];
      elements.hint.textContent = hints.join(' • ');

      if (state.active && state.colorMode > 0) {
        elements.modeIndicator.textContent = COLOR_NAMES[state.colorMode];
        elements.modeIndicator.classList.add('visible');
      } else {
        elements.modeIndicator.classList.remove('visible');
      }
    };

    const applyState = () => {
      updateClasses();
      updateUI();
    };

    const toggleActive = () => {
      state.active = !state.active;
      applyState();
      storage.save();
    };

    const cycleColor = () => {
      state.colorMode = (state.colorMode + 1) % COLOR_MODES.length;
      state.active = true;
      elements.circle.classList.add('color-shifting');
      setTimeout(() => elements.circle.classList.remove('color-shifting'), COLOR_SHIFT_DURATION);
      applyState();
      storage.save();
    };

    const resetState = () => {
      state = { active: false, colorMode: 0 };
      applyState();
      storage.save();
    };

    const handleDblClick = (e) => {
      e.preventDefault();
      cycleColor();
    };

    const handleTouchEnd = (e) => {
      const currentTime = Date.now();
      const tapLength = currentTime - lastTapTime;
      if (tapLength < TAP_DELAY && tapLength > 0) {
        e.preventDefault();
        cycleColor();
      } else {
        lastTapTime = currentTime;
      }
    };

    const handleKeyDown = (e) => {
      const key = e.key.toLowerCase();
      if (key === ' ' || key === 'enter') {
        e.preventDefault();
        toggleActive();
      } else if (key === 'c') {
        e.preventDefault();
        cycleColor();
      } else if (key === 'r') {
        e.preventDefault();
        resetState();
      }
    };

    elements.circle.addEventListener('click', toggleActive);
    elements.circle.addEventListener('dblclick', handleDblClick);
    elements.circle.addEventListener('touchend', handleTouchEnd);
    elements.circle.addEventListener('keydown', handleKeyDown);
    elements.cycleBtn.addEventListener('click', cycleColor);
    elements.resetBtn.addEventListener('click', resetState);

    storage.load();
    applyState();
    elements.circle.focus();
  </script>
</body>
</html>

